import Component from 'flarum/common/Component';
import Icon from 'flarum/common/components/Icon';
import Tooltip from 'flarum/common/components/Tooltip';
import extractText from 'flarum/common/utils/extractText';
import PanelLayout from '../PanelLayout';
import KeyValueList from '../KeyValueList';
import { trans } from '../../config';
import { count } from '../../utils/format';
/**
 * The settings table, grouped by the extension that owns each key.
 */
export default class SettingsPanel extends Component {
  filter = '';
  view(vnode) {
    const data = this.attrs.data;
    const groups = this.matches();
    return m(PanelLayout, {
      className: "DebugbarSettings",
      stats: [{
        label: trans('settings.count'),
        value: count(data.count)
      }, {
        label: trans('settings.groups'),
        value: count(data.groups.length)
      }],
      filter: this.filter,
      filterPlaceholder: trans('settings.filter'),
      onfilter: query => this.filter = query,
      isEmpty: !groups.length,
      empty: data.count ? trans('no_matches') : trans('settings.empty')
    }, m("div", {
      className: "DebugbarSections"
    }, groups.map(group => m("section", {
      className: "DebugbarSection",
      key: group.name
    }, m("h3", {
      className: "DebugbarSection-title"
    }, group.name), m(KeyValueList, {
      entries: group.settings.map(setting => [m("code", null, setting.name), this.value(setting)])
    })))));
  }
  value(setting) {
    if (setting.sensitive) {
      return m(Tooltip, {
        text: extractText(trans('settings.redacted'))
      }, m("span", {
        className: "DebugbarSettings-redacted"
      }, m(Icon, {
        name: "fas fa-lock"
      }), " ", setting.value));
    }
    return setting.value === '' ? m("span", {
      className: "DebugbarKeyValue-blank"
    }, trans('blank')) : m("code", null, setting.value);
  }
  matches() {
    const needle = this.filter.trim().toLowerCase();
    if (!needle) return this.attrs.data.groups;

    // A group matches wholesale when its own name matches, so filtering by
    // extension id shows everything that extension owns. Matching on the full
    // key rather than the shortened name keeps the prefix searchable even
    // though the rows no longer show it.
    return this.attrs.data.groups.map(group => group.name.toLowerCase().includes(needle) ? group : {
      ...group,
      settings: group.settings.filter(setting => setting.key.toLowerCase().includes(needle))
    }).filter(group => group.settings.length > 0);
  }
}
flarum.reg.add('datlechin-debugbar', 'common/components/panels/SettingsPanel', SettingsPanel);