import Component from 'flarum/common/Component';
import PanelLayout from '../PanelLayout';
import { trans } from '../../config';
/**
 * What a collector gets when nothing has registered a panel for it.
 *
 * An extension can add a collector with the extender and see its data straight
 * away, then write a panel for it later — rather than having to write both
 * before either is any use.
 */
export default class GenericPanel extends Component {
  view(vnode) {
    const data = this.attrs.data;
    const empty = data === null || data === undefined || typeof data === 'object' && !Object.keys(data).length;
    return m(PanelLayout, {
      className: "DebugbarGeneric",
      isEmpty: empty,
      empty: trans('empty')
    }, m("pre", {
      className: "DebugbarCode"
    }, JSON.stringify(data, null, 2)));
  }
}
flarum.reg.add('datlechin-debugbar', 'common/components/panels/GenericPanel', GenericPanel);