import Component from 'flarum/common/Component';
import PanelLayout from '../PanelLayout';
import { trans } from '../../config';
import { count, duration } from '../../utils/format';
/**
 * Events dispatched during the request, in order.
 */
export default class EventsPanel extends Component {
  filter = '';
  view(vnode) {
    const data = this.attrs.data;
    const matches = this.matches(data.events);
    return m(PanelLayout, {
      className: "DebugbarEvents",
      stats: [{
        label: trans('events.count'),
        value: count(data.count)
      }, {
        label: trans('events.listed'),
        value: count(data.events.length)
      }],
      filter: this.filter,
      filterPlaceholder: trans('events.filter'),
      onfilter: query => this.filter = query,
      isEmpty: !matches.length && !data.collapsed.length,
      empty: data.events.length ? trans('no_matches') : trans('events.empty')
    }, m("ol", {
      className: "DebugbarEvents-list"
    }, matches.map((event, index) => m("li", {
      className: "DebugbarEvent",
      key: index
    }, m("span", {
      className: "DebugbarEvent-offset"
    }, duration(Math.max(0, event.time - this.attrs.start))), m("code", {
      className: "DebugbarEvent-name"
    }, event.name), !!event.payload.length && m("span", {
      className: "DebugbarEvent-payload"
    }, event.payload.join(', '))))), data.dropped > 0 && m("p", {
      className: "Debugbar-truncated"
    }, trans('events.dropped', {
      count: count(data.dropped)
    })), !!data.collapsed.length && this.collapsed());
  }
  matches(events) {
    const needle = this.filter.trim().toLowerCase();
    return needle ? events.filter(event => event.name.toLowerCase().includes(needle)) : events;
  }

  /**
   * Eloquent's model events, counted rather than listed. There are hundreds of
   * them on any page that loads a list, and the totals are the only part
   * anybody reads.
   */
  collapsed() {
    return m("section", {
      className: "DebugbarSection DebugbarEvents-collapsed"
    }, m("h3", {
      className: "DebugbarSection-title"
    }, trans('events.collapsed_title')), m("p", {
      className: "DebugbarSection-note"
    }, trans('events.collapsed_help')), m("ul", {
      className: "DebugbarEvents-collapsedList"
    }, this.attrs.data.collapsed.map(entry => m("li", {
      key: entry.name
    }, m("code", null, entry.name), m("span", {
      className: "DebugbarBadge"
    }, count(entry.count))))));
  }
}
flarum.reg.add('datlechin-debugbar', 'common/components/panels/EventsPanel', EventsPanel);